def polish(s):
    # A restricted prose fix: separate a prose word/variable from a following number.
    # It is applied only to prose, never IDs, codes, formulas or SVG geometry.
    s=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ', s)
    s=re.sub(r'(?<=[,;:])(?=[A-Za-z0-9])', ' ', s)
    return s.replace('TACCG AATGATT','TACCGAATGATT').replace('DNA5′','DNA 5′').replace('RNA5′','RNA 5′').replace('per100','per 100')

def write():
    assert len(QUESTIONS)==50 and [q['number'] for q in QUESTIONS]==list(range(701,751))
    assert Counter(q['level'] for q in QUESTIONS)=={'sl':20,'ahl':30}
    assert Counter(q['syllabusCode'] for q in QUESTIONS)=={'A1.1':5,'A1.2':7,'A2.1':5,'A2.2':7,'A2.3':5,'A3.1':6,'A3.2':5,'A4.1':5,'A4.2':5}
    for q,r in zip(QUESTIONS,RECORDS):
        for k in ['stem','answerSummary']:q[k]=polish(q[k])
        for p in q['parts']:p['prompt']=polish(p['prompt'])
        for g in q['markScheme']:
            for st in g['steps']:st['text']=polish(st['text'])
        q['diagramSvg']=re.sub(r'(<text\b[^>]*>)(.*?)(</text>)',lambda m:m[1]+polish(m[2])+m[3],q['diagramSvg'])
        r['canonicalQuestionSha256']=hashlib.sha256(json.dumps(q,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
    DEST.parent.mkdir(parents=True,exist_ok=True);REVIEW.parent.mkdir(parents=True,exist_ok=True)
    payload=json.dumps(QUESTIONS,ensure_ascii=False,indent=2)+'\n'
    DEST.write_text(payload,encoding='utf-8',newline='\n')
    report={'status':'passed','questions':50,'subject':'biology','theme':'A','levels':dict(Counter(q['level'] for q in QUESTIONS)),'difficulty':{'hard':50},'substantiveDiagrams':50,'diagramTypes':'Scientific spatial/structural schematics, graphs, bar charts, rooted trees, character-state plots and model timelines; no raster micrographs or text-only cards.','visualReview':'All50 diagrams rasterized and inspected in five contact sheets; revised compound leaves to separate leaflets, reduced bird digits to three, removed artificial scatter joins, separated footer/scale text and shortened a vertical axis. Selected revised diagrams inspected at full size.','authorCheckCount':sum(r['executableChecks'] for r in RECORDS),'sha256':hashlib.sha256(DEST.read_bytes()).hexdigest(),'scopeSources':['https://xmltwo.ibo.org/publications/EAD/2026_EN/GR4/GR4-Biology_EN.pdf','https://www.ibo.org/globalassets/new-structure/programmes/dp/pdfs/biology-hl-sl-specimen-papers-1a-2b-2-en.pdf'],'reviewLimitations':'AI author checks and subsequent independent agent review; not human IB examiner moderation. Constructed evidence cannot be cited as real research.','records':RECORDS}
    REVIEW.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
    print(json.dumps({k:report[k] for k in ['status','questions','levels','authorCheckCount','sha256']}))

if __name__=='__main__':write()
